25:/**
26: * Provider-scoped booking response router under `/api/v1/providers`.
27: */
28:export function createBookingProviderResponseRouter(
29:  dependencies: BookingResponseRouterDependencies,
30:): Router {
31:  const controller = createBookingResponseController({
32:    service: dependencies.service,
33:  });
34:  const router = Router({ mergeParams: true });
35:  router.use(dependencies.authenticateAccess);
36:  router.use(requireFullAuthentication);
37:  const rateLimit = (scope: string) =>
38:    createRateLimitMiddleware({
39:      limiter: dependencies.rateLimiter,
40:      scope: `bookings-response-${scope}`,
41:      limit: MUTATE.limit,
42:      windowSeconds: MUTATE.windowSeconds,
43:      subject: (ip) => hashedIpSubject(dependencies.privacyHashSecret, ip),
44:    });
45:
46:  router.get("/:providerId/bookings/inbox", (req, res, next) => {
47:    void controller.inbox(req, res, next);
48:  });
49:  router.get("/:providerId/bookings/:bookingId", (req, res, next) => {
50:    void controller.providerGet(req, res, next);
51:  });
52:  router.post(
53:    "/:providerId/bookings/:bookingId/accept",
54:    rateLimit("accept"),
55:    (req, res, next) => {
56:      void controller.accept(req, res, next);
57:    },
58:  );
59:  router.post(
60:    "/:providerId/bookings/:bookingId/reject",
61:    rateLimit("reject"),
62:    (req, res, next) => {
63:      void controller.reject(req, res, next);
64:    },
65:  );
66:  router.post(
67:    "/:providerId/bookings/:bookingId/cancel",
68:    rateLimit("provider-cancel"),
69:    (req, res, next) => {
70:      void controller.providerCancel(req, res, next);
71:    },
72:  );
73:  return router;
74:}
