215:/**
216: * @desc Provider inbox, accept/reject, lazy expiry, and cancellation commands.
217: * @access Bookings application
218: */
219:export class BookingResponseService {
220:  public constructor(private readonly deps: BookingResponseServiceDependencies) {}
221:
222:  public async listInbox(input: {
223:    readonly actorUserId: string;
224:    readonly providerId: string;
225:    readonly limit: number;
226:  }): Promise<{ readonly items: readonly InboxItem[]; readonly nextCursor: null }> {
227:    await this.deps.assertActiveProviderManager(input.providerId, input.actorUserId);
228:    const db = clientOf(this.deps);
229:    const now = this.deps.now();
230:    const pending = await db.bookingResponse.findMany({
231:      where: {
232:        providerId: input.providerId,
233:        status: "PENDING",
234:        booking: { status: "CONFIRMED", providerId: input.providerId },
235:      },
236:      include: { booking: true },
237:      orderBy: { expiresAt: "asc" },
238:      take: 100,
239:    });
240:    const items: InboxItem[] = [];
241:    for (const row of pending) {
242:      if (row.expiresAt.getTime() <= now.getTime()) {
243:        await this.expireIfPending(row.bookingId);
244:        continue;
245:      }
246:      items.push({
247:        bookingId: row.bookingId,
248:        status: "CONFIRMED",
249:        startsAt: row.booking.startsAt.toISOString(),
250:        endsAt: row.booking.endsAt.toISOString(),
251:        responseStatus: "PENDING",
252:        expiresAt: row.expiresAt.toISOString(),
253:        version: row.booking.version,
254:      });
255:      if (items.length >= input.limit) break;
256:    }
257:    return { items, nextCursor: null };
258:  }
