260:  public async getProviderDossier(input: {
261:    readonly actorUserId: string;
262:    readonly providerId: string;
263:    readonly bookingId: string;
264:  }): Promise<BookingDossier> {
265:    await this.deps.assertActiveProviderManager(input.providerId, input.actorUserId);
266:    await this.expireIfPending(input.bookingId);
267:    const dossier = requirePresent(
268:      await this.loadDossier(input.bookingId),
269:      () => bookingError("NOT_FOUND"),
270:    );
271:    failWhen(dossier.providerId !== input.providerId, () => bookingError("NOT_FOUND"));
272:    return dossier;
