308:  public async accept(input: {
309:    readonly actorUserId: string;
310:    readonly providerId: string;
311:    readonly bookingId: string;
312:    readonly version: number;
313:    readonly idempotencyKey: string;
314:  }): Promise<{ readonly bookingId: string; readonly status: "ACCEPTED"; readonly version: number; readonly responseStatus: "ACCEPTED" }> {
315:    return this.withActorIdempotency({
316:      actorUserId: input.actorUserId,
317:      commandType: "ACCEPT",
318:      idempotencyKey: input.idempotencyKey,
319:      bookingId: input.bookingId,
320:      request: { bookingId: input.bookingId, version: input.version, providerId: input.providerId },
321:      run: async (tx) => {
322:        await this.deps.assertActiveProviderManager(input.providerId, input.actorUserId);
323:        await this.expireIfPending(input.bookingId, tx);
324:        const expired = await tx.bookingResponse.findUnique({
325:          where: { bookingId: input.bookingId },
326:        });
327:        failWhen(isExpiredResponse(expired), () => bookingError("RESPONSE_EXPIRED"));
328:        const booking = await this.requireProviderBooking(tx, input.bookingId, input.providerId);
329:        if (booking.status === "ACCEPTED") {
330:          return {
331:            bookingId: booking.id,
332:            status: "ACCEPTED" as const,
333:            version: booking.version,
334:            responseStatus: "ACCEPTED" as const,
335:          };
336:        }
337:        failWhen(booking.status !== "CONFIRMED", () => bookingError("TRANSITION_NOT_AVAILABLE"));
338:        failWhen(booking.version !== input.version, () => bookingError("CONFLICT"));
339:        await this.requireRule(tx, "PROVIDER", "CONFIRMED", "ACCEPTED");
340:        const response = await tx.bookingResponse.findUnique({ where: { bookingId: input.bookingId } });
341:        failWhen(!isPendingResponse(response), () => bookingError("TRANSITION_NOT_AVAILABLE"));
342:        failWhen(response.expiresAt.getTime() <= this.deps.now().getTime(), () => bookingError("RESPONSE_EXPIRED"));
343:        const claimed = await tx.booking.updateMany({
344:          where: { id: input.bookingId, status: "CONFIRMED", version: input.version },
345:          data: { status: "ACCEPTED", version: { increment: 1 } },
346:        });
347:        failWhen(claimed.count !== 1, () => bookingError("CONFLICT"));
348:        await tx.bookingResponse.update({
349:          where: { bookingId: input.bookingId },
350:          data: {
351:            status: "ACCEPTED",
352:            decidedAt: this.deps.now(),
353:            decidedByUserId: input.actorUserId,
354:          },
355:        });
356:        await tx.bookingStatusHistory.create({
357:          data: {
358:            bookingId: input.bookingId,
359:            fromStatus: "CONFIRMED",
360:            toStatus: "ACCEPTED",
361:            actorUserId: input.actorUserId,
362:            actorType: "PROVIDER",
363:            reasonCode: "PROVIDER_ACCEPTED",
364:          },
365:        });
366:        await this.insertIntent(tx, {
367:          bookingId: input.bookingId,
368:          template: "BOOKING_ACCEPTED",
369:          recipientUserId: booking.customerUserId,
370:          locale: booking.locale,
371:          idempotencyKey: shaIdempotency(["BOOKING_ACCEPTED", input.bookingId]),
372:        });
373:        return {
374:          bookingId: input.bookingId,
375:          status: "ACCEPTED" as const,
376:          version: input.version + 1,
377:          responseStatus: "ACCEPTED" as const,
378:        };
379:      },
380:    });
381:  }
