383:  public async reject(input: {
384:    readonly actorUserId: string;
385:    readonly providerId: string;
386:    readonly bookingId: string;
387:    readonly version: number;
388:    readonly reasonCode: string;
389:    readonly idempotencyKey: string;
390:  }): Promise<{
391:    readonly bookingId: string;
392:    readonly status: "CANCELLED";
393:    readonly version: number;
394:    readonly responseStatus: "REJECTED";
395:    readonly cancellationId: string;
396:  }> {
397:    return this.withActorIdempotency({
398:      actorUserId: input.actorUserId,
399:      commandType: "REJECT",
400:      idempotencyKey: input.idempotencyKey,
401:      bookingId: input.bookingId,
402:      request: {
403:        bookingId: input.bookingId,
404:        version: input.version,
405:        providerId: input.providerId,
406:        reasonCode: input.reasonCode,
407:      },
408:      run: async (tx) => {
409:        await this.deps.assertActiveProviderManager(input.providerId, input.actorUserId);
410:        await this.expireIfPending(input.bookingId, tx);
411:        const expired = await tx.bookingResponse.findUnique({
412:          where: { bookingId: input.bookingId },
413:        });
414:        failWhen(isExpiredResponse(expired), () => bookingError("RESPONSE_EXPIRED"));
415:        const booking = await this.requireProviderBooking(tx, input.bookingId, input.providerId);
416:        if (booking.status === "CANCELLED") {
417:          const existing = await tx.bookingCancellation.findUnique({
418:            where: { bookingId: input.bookingId },
419:          });
420:          if (existing !== null) {
421:            return {
422:              bookingId: booking.id,
423:              status: "CANCELLED" as const,
424:              version: booking.version,
425:              responseStatus: "REJECTED" as const,
426:              cancellationId: existing.id,
427:            };
428:          }
429:        }
430:        failWhen(booking.status !== "CONFIRMED", () => bookingError("TRANSITION_NOT_AVAILABLE"));
431:        failWhen(booking.version !== input.version, () => bookingError("CONFLICT"));
432:        const reason = requirePresent(
433:          await tx.cancellationReason.findFirst({
434:            where: {
435:              code: input.reasonCode,
436:              actor: "PROVIDER",
437:              purpose: "REJECT",
438:              active: true,
439:            },
440:          }),
441:          () => bookingError("VALIDATION_FAILED", { reason: "UNKNOWN_REASON" }),
442:        );
443:        await this.requireRule(tx, "PROVIDER", "CONFIRMED", "CANCELLED");
444:        const cancellationId = await this.terminalCancel(tx, {
445:          bookingId: input.bookingId,
446:          expectedVersion: input.version,
447:          fromStatus: "CONFIRMED",
448:          actorKind: "PROVIDER",
449:          actorUserId: input.actorUserId,
450:          actorType: "PROVIDER",
451:          reasonId: reason.id,
452:          reasonCode: reason.code,
453:          responseStatus: "REJECTED",
454:          notifyTemplate: "BOOKING_REJECTED",
455:          recipientUserId: booking.customerUserId,
456:          locale: booking.locale,
457:        });
458:        return {
459:          bookingId: input.bookingId,
460:          status: "CANCELLED" as const,
461:          version: input.version + 1,
462:          responseStatus: "REJECTED" as const,
463:          cancellationId,
464:        };
465:      },
466:    });
467:  }
