470:    readonly actorUserId: string;
471:    readonly providerId: string;
472:    readonly bookingId: string;
473:    readonly version: number;
474:    readonly reasonCode: string;
475:    readonly idempotencyKey: string;
476:  }): Promise<{ readonly bookingId: string; readonly status: "CANCELLED"; readonly version: number; readonly cancellationId: string }> {
477:    return this.withActorIdempotency({
478:      actorUserId: input.actorUserId,
479:      commandType: "PROVIDER_CANCEL",
480:      idempotencyKey: input.idempotencyKey,
481:      bookingId: input.bookingId,
482:      request: {
483:        bookingId: input.bookingId,
484:        version: input.version,
485:        providerId: input.providerId,
486:        reasonCode: input.reasonCode,
487:      },
488:      run: async (tx) => {
489:        await this.deps.assertActiveProviderManager(input.providerId, input.actorUserId);
490:        const booking = await this.requireProviderBooking(tx, input.bookingId, input.providerId);
491:        failWhen(booking.status === "CONFIRMED", () => bookingError("TRANSITION_NOT_AVAILABLE"));
492:        if (booking.status === "CANCELLED") {
493:          const existing = await tx.bookingCancellation.findUnique({
494:            where: { bookingId: input.bookingId },
