503:          }
504:        }
505:        failWhen(booking.status !== "ACCEPTED", () => bookingError("TRANSITION_NOT_AVAILABLE"));
506:        failWhen(booking.version !== input.version, () => bookingError("CONFLICT"));
507:        const reason = requirePresent(
508:          await tx.cancellationReason.findFirst({
509:            where: {
510:              code: input.reasonCode,
511:              actor: "PROVIDER",
512:              purpose: "CANCEL",
513:              active: true,
514:            },
515:          }),
516:          () => bookingError("VALIDATION_FAILED", { reason: "UNKNOWN_REASON" }),
517:        );
518:        await this.requireRule(tx, "PROVIDER", "ACCEPTED", "CANCELLED");
519:        const cancellationId = await this.terminalCancel(tx, {
520:          bookingId: input.bookingId,
521:          expectedVersion: input.version,
522:          fromStatus: "ACCEPTED",
523:          actorKind: "PROVIDER",
524:          actorUserId: input.actorUserId,
525:          actorType: "PROVIDER",
526:          reasonId: reason.id,
527:          reasonCode: reason.code,
528:          notifyTemplate: "BOOKING_CANCELLED",
529:          recipientUserId: booking.customerUserId,
530:          locale: booking.locale,
531:        });
532:        return {
533:          bookingId: input.bookingId,
534:          status: "CANCELLED" as const,
535:          version: input.version + 1,
536:          cancellationId,
537:        };
538:      },
539:    });
540:  }
