542:  public async staffCancel(input: {
543:    readonly actorUserId: string;
544:    readonly bookingId: string;
545:    readonly version: number;
546:    readonly reasonCode: string;
547:    readonly idempotencyKey: string;
548:  }): Promise<{ readonly bookingId: string; readonly status: "CANCELLED"; readonly version: number; readonly cancellationId: string }> {
549:    return this.withActorIdempotency({
550:      actorUserId: input.actorUserId,
551:      commandType: "STAFF_CANCEL",
552:      idempotencyKey: input.idempotencyKey,
553:      bookingId: input.bookingId,
554:      request: {
555:        bookingId: input.bookingId,
556:        version: input.version,
557:        reasonCode: input.reasonCode,
558:      },
559:      run: async (tx) => {
560:        failWhen(!(await this.deps.isStaffAdmin(input.actorUserId)), () => bookingError("FORBIDDEN"));
561:        await this.expireIfPending(input.bookingId, tx);
562:        const booking = requirePresent(
563:          await tx.booking.findUnique({ where: { id: input.bookingId } }),
564:          () => bookingError("NOT_FOUND"),
565:        );
566:        failWhen(!canCancelAfterConfirm(booking.status), () => bookingError("TRANSITION_NOT_AVAILABLE"));
567:        failWhen(booking.version !== input.version, () => bookingError("CONFLICT"));
568:        const reason = requirePresent(
569:          await tx.cancellationReason.findFirst({
570:            where: {
571:              code: input.reasonCode,
572:              actor: "STAFF_ADMIN",
573:              purpose: "CANCEL",
574:              active: true,
575:            },
576:          }),
577:          () => bookingError("VALIDATION_FAILED", { reason: "UNKNOWN_REASON" }),
578:        );
579:        await this.requireRule(tx, "STAFF_ADMIN", booking.status, "CANCELLED");
580:        const recipient = notifyRecipient(
581:          await this.deps.resolveProviderOwnerUserId(booking.providerId),
582:          booking.customerUserId,
583:        );
584:        const cancellationId = await this.terminalCancel(tx, {
585:          bookingId: input.bookingId,
586:          expectedVersion: input.version,
587:          fromStatus: booking.status,
588:          actorKind: "STAFF_ADMIN",
589:          actorUserId: input.actorUserId,
590:          actorType: "STAFF_ADMIN",
591:          reasonId: reason.id,
592:          reasonCode: reason.code,
593:          notifyTemplate: "BOOKING_CANCELLED",
594:          recipientUserId: recipient,
595:          locale: booking.locale,
596:        });
597:        return {
598:          bookingId: input.bookingId,
599:          status: "CANCELLED" as const,
600:          version: input.version + 1,
601:          cancellationId,
602:        };
603:      },
604:    });
605:  }
