657:  public async ensurePendingResponse(
658:    tx: BookingTx,
659:    input: {
660:      readonly bookingId: string;
661:      readonly providerId: string;
662:      readonly countryId: string;
663:      readonly customerUserId: string;
664:      readonly locale: "AR" | "EN";
665:    },
666:  ): Promise<void> {
667:    const hours = requirePresent(
668:      await this.deps.readResponseHours(input.countryId),
669:      () => bookingError("DEPENDENCY_FAILURE", { reason: "PROVIDER_RESPONSE_HOURS" }),
670:    );
671:    const existing = await tx.bookingResponse.findUnique({
672:      where: { bookingId: input.bookingId },
673:    });
674:    if (existing !== null) {
675:      return;
676:    } else {
677:    const ownerUserId = requirePresent(
678:      await this.deps.resolveProviderOwnerUserId(input.providerId),
679:      () => bookingError("DEPENDENCY_FAILURE", { reason: "PROVIDER_OWNER" }),
680:    );
681:    const expiresAt = new Date(this.deps.now().getTime() + hours * 60 * 60 * 1000);
682:    await tx.bookingResponse.create({
683:      data: {
684:        bookingId: input.bookingId,
685:        providerId: input.providerId,
686:        status: "PENDING",
687:        expiresAt,
688:      },
689:    });
690:    await this.insertIntent(tx, {
691:      bookingId: input.bookingId,
692:      template: "BOOKING_CONFIRMED_FOR_PROVIDER",
693:      recipientUserId: ownerUserId,
694:      locale: input.locale,
695:      idempotencyKey: shaIdempotency([
696:        "BOOKING_CONFIRMED_FOR_PROVIDER",
697:        input.bookingId,
698:      ]),
699:    });
700:    }
701:  }
