703:  private async expireIfPending(bookingId: string, tx?: BookingTx): Promise<void> {
704:    const run = async (db: BookingTx) => {
705:      const response = await db.bookingResponse.findUnique({
706:        where: { bookingId },
707:        include: { booking: true },
708:      });
709:      if (!isPendingResponse(response)) {
710:        return;
711:      } else if (response.expiresAt.getTime() > this.deps.now().getTime()) {
712:        return;
713:      } else if (response.booking.status !== "CONFIRMED") {
714:        return;
715:      } else {
716:      const reason = requirePresent(
717:        await db.cancellationReason.findUnique({
718:          where: { code: "PROVIDER_RESPONSE_EXPIRED" },
719:        }),
720:        () => bookingError("DEPENDENCY_FAILURE", { reason: "EXPIRY_REASON" }),
721:      );
722:      await this.requireRule(db, "SYSTEM", "CONFIRMED", "CANCELLED");
723:      await this.terminalCancel(db, {
724:        bookingId,
725:        expectedVersion: response.booking.version,
726:        fromStatus: "CONFIRMED",
727:        actorKind: "SYSTEM",
728:        actorUserId: null,
729:        actorType: "SYSTEM",
730:        reasonId: reason.id,
731:        reasonCode: reason.code,
732:        responseStatus: "EXPIRED",
733:        notifyTemplate: "BOOKING_RESPONSE_EXPIRED",
734:        recipientUserId: response.booking.customerUserId,
735:        locale: response.booking.locale,
736:      });
737:      }
738:    };
739:    try {
740:      if (tx !== undefined) {
741:        await run(tx);
742:        return;
743:      } else {
744:        await clientOf(this.deps).$transaction((nested) => run(nested));
745:      }
746:    } catch (error) {
747:      if (isConflictError(error)) {
748:        return;
749:      } else {
750:        throw error;
751:      }
752:    }
753:  }
754:
755:  private async terminalCancel(
756:    tx: BookingTx,
757:    input: {
758:      readonly bookingId: string;
759:      readonly expectedVersion: number;
760:      readonly fromStatus: string;
761:      readonly actorKind: "CUSTOMER" | "PROVIDER" | "STAFF_ADMIN" | "SYSTEM";
762:      readonly actorUserId: string | null;
763:      readonly actorType: "CUSTOMER" | "PROVIDER" | "STAFF_ADMIN" | "SYSTEM";
764:      readonly reasonId: string;
765:      readonly reasonCode: string;
766:      readonly responseStatus?: "REJECTED" | "EXPIRED";
767:      readonly notifyTemplate: "BOOKING_REJECTED" | "BOOKING_RESPONSE_EXPIRED" | "BOOKING_CANCELLED";
768:      readonly recipientUserId: string;
769:      readonly locale: "AR" | "EN";
770:    },
771:  ): Promise<string> {
772:    const claimed = await tx.booking.updateMany({
773:      where: {
774:        id: input.bookingId,
775:        status: input.fromStatus as BookingStatusName,
776:        version: input.expectedVersion,
777:      },
778:      data: {
779:        status: "CANCELLED",
780:        version: { increment: 1 },
781:        cancelledAt: this.deps.now(),
782:      },
783:    });
784:    failWhen(claimed.count !== 1, () => bookingError("CONFLICT"));
785:    if (input.responseStatus !== undefined) {
786:      await tx.bookingResponse.updateMany({
787:        where: { bookingId: input.bookingId, status: "PENDING" },
788:        data: {
789:          status: input.responseStatus,
790:          decidedAt: this.deps.now(),
791:          decidedByUserId: input.actorUserId,
792:          ...(input.responseStatus === "REJECTED" ? { rejectReasonId: input.reasonId } : {}),
793:        },
794:      });
795:    } else {
796:      // Customer and provider-accepted cancels keep the response row unchanged.
797:    }
798:    const cancellation = await tx.bookingCancellation.create({
799:      data: {
800:        bookingId: input.bookingId,
801:        actorKind: input.actorKind,
802:        actorUserId: input.actorUserId,
803:        reasonId: input.reasonId,
804:        fromStatus: input.fromStatus,
805:      },
806:    });
807:    await tx.bookingStatusHistory.create({
808:      data: {
809:        bookingId: input.bookingId,
810:        fromStatus: input.fromStatus,
811:        toStatus: "CANCELLED",
812:        actorUserId: input.actorUserId,
813:        actorType: input.actorType,
814:        reasonCode: input.reasonCode,
815:      },
816:    });
817:    await this.insertIntent(tx, {
818:      bookingId: input.bookingId,
819:      template: input.notifyTemplate,
820:      recipientUserId: input.recipientUserId,
821:      locale: input.locale,
822:      idempotencyKey: shaIdempotency([input.notifyTemplate, input.bookingId]),
823:    });
824:    return cancellation.id;
825:  }
