827:  private async insertIntent(
828:    tx: BookingTx,
829:    input: {
830:      readonly bookingId: string;
831:      readonly template:
832:        | "BOOKING_CONFIRMED_FOR_PROVIDER"
833:        | "BOOKING_ACCEPTED"
834:        | "BOOKING_REJECTED"
835:        | "BOOKING_RESPONSE_EXPIRED"
836:        | "BOOKING_CANCELLED";
837:      readonly recipientUserId: string;
838:      readonly locale: "AR" | "EN";
839:      readonly idempotencyKey: string;
840:    },
841:  ): Promise<void> {
842:    await tx.bookingNotificationIntent.upsert({
843:      where: { idempotencyKey: input.idempotencyKey },
844:      create: {
845:        bookingId: input.bookingId,
846:        template: input.template,
847:        locale: input.locale,
848:        recipientUserId: input.recipientUserId,
849:        idempotencyKey: input.idempotencyKey,
850:        safeVariables: { bookingId: input.bookingId },
851:        status: "PENDING",
852:      },
853:      update: {},
854:    });
855:  }
