857:  private async requireRule(
858:    tx: BookingTx,
859:    actor: "CUSTOMER" | "PROVIDER" | "SYSTEM" | "STAFF_ADMIN",
860:    fromStatus: string,
861:    toStatus: string,
862:  ): Promise<void> {
863:    const rule = await tx.statusTransitionRule.findFirst({
864:      where: { actor, fromStatus, toStatus, executable: true },
865:      select: { id: true },
866:    });
867:    failWhen(rule === null, () => bookingError("TRANSITION_NOT_AVAILABLE"));
