879:  private async loadDossier(bookingId: string): Promise<BookingDossier | null> {
880:    const db = clientOf(this.deps);
881:    const booking = await db.booking.findUnique({
882:      where: { id: bookingId },
883:      include: {
884:        address: true,
885:        priceBreakdown: true,
886:        response: true,
887:        cancellation: { include: { reason: true } },
888:      },
889:    });
890:    if (booking === null) {
891:      return null;
892:    } else {
893:    return {
894:      bookingId: booking.id,
895:      status: booking.status,
896:      providerId: booking.providerId,
897:      customerUserId: booking.customerUserId,
898:      startsAt: booking.startsAt.toISOString(),
899:      endsAt: booking.endsAt.toISOString(),
900:      addressText: booking.address === null ? null : booking.address.addressText,
901:      crewPreference: booking.crewPreference,
902:      version: booking.version,
903:      quote: quoteProjection(booking.priceBreakdown),
904:      response: responseProjection(booking.response),
905:      cancellation: cancellationProjection(booking.cancellation),
906:    };
907:    }
908:  }
