910:  private async withActorIdempotency<T>(input: {
911:    readonly actorUserId: string;
912:    readonly commandType: "ACCEPT" | "REJECT" | "PROVIDER_CANCEL" | "STAFF_CANCEL";
913:    readonly idempotencyKey: string;
914:    readonly bookingId: string;
915:    readonly request: unknown;
916:    readonly run: (tx: BookingTx) => Promise<T>;
917:  }): Promise<T> {
918:    const db = clientOf(this.deps);
919:    const requestHash = requestHashOf(input.request);
920:    const existing = await db.bookingActorCommand.findUnique({
921:      where: {
922:        actorUserId_commandType_idempotencyKey: {
923:          actorUserId: input.actorUserId,
924:          commandType: input.commandType,
925:          idempotencyKey: input.idempotencyKey,
926:        },
927:      },
928:    });
929:    if (existing !== null) {
930:      failWhen(existing.requestHash !== requestHash, () => bookingError("IDEMPOTENCY_BODY_MISMATCH"));
931:      return existing.responseJson as T;
932:    } else {
933:    return db.$transaction(async (tx) => {
934:      const created = await tx.bookingActorCommand.create({
935:        data: {
936:          actorUserId: input.actorUserId,
937:          commandType: input.commandType,
938:          idempotencyKey: input.idempotencyKey,
939:          bookingId: input.bookingId,
940:          requestHash,
941:          responseJson: {},
942:        },
943:      });
944:      const result = await input.run(tx);
945:      await tx.bookingActorCommand.update({
946:        where: { id: created.id },
947:        data: { responseJson: result },
948:      });
949:      return result;
950:    });
951:    }
952:  }
953:}
