58:/**
59: * Thin HTTP adapters for provider/staff booking response commands.
60: * @access Bookings HTTP
61: */
62:export function createBookingResponseController(
63:  dependencies: BookingResponseControllerDependencies,
64:): {
65:  readonly inbox: RequestHandler;
66:  readonly providerGet: RequestHandler;
67:  readonly accept: RequestHandler;
68:  readonly reject: RequestHandler;
69:  readonly providerCancel: RequestHandler;
70:  readonly reasons: RequestHandler;
71:  readonly staffGet: RequestHandler;
72:  readonly staffCancel: RequestHandler;
73:} {
74:  return {
75:    /**
76:     * @desc List the selected provider's pending confirmed bookings.
77:     * @route GET /api/v1/providers/:providerId/bookings/inbox
78:     * @access Provider OWNER/ADMIN
79:     */
80:    async inbox(request, response, next): Promise<void> {
81:      try {
82:        const params = providerInboxParamsSchema.parse(request.params);
83:        const query = inboxQuerySchema.parse(request.query);
84:        const data = await dependencies.service.listInbox({
85:          actorUserId: principalOf(response).userId,
86:          providerId: params.providerId,
87:          limit: query.limit === undefined ? 20 : query.limit,
88:        });
89:        sendSuccess(request, response, 200, data);
90:      } catch (error) {
91:        next(mapZod(error));
92:      }
93:    },
94:
95:    /**
96:     * @desc Read the selected-provider booking dossier.
97:     * @route GET /api/v1/providers/:providerId/bookings/:bookingId
98:     * @access Provider OWNER/ADMIN of the selected provider
99:     */
100:    async providerGet(request, response, next): Promise<void> {
101:      try {
102:        const params = providerBookingParamsSchema.parse(request.params);
103:        const data = await dependencies.service.getProviderDossier({
104:          actorUserId: principalOf(response).userId,
105:          providerId: params.providerId,
106:          bookingId: params.bookingId,
107:        });
108:        sendSuccess(request, response, 200, data);
109:      } catch (error) {
110:        next(mapZod(error));
111:      }
112:    },
113:
114:    /**
115:     * @desc Accept a confirmed booking.
116:     * @route POST /api/v1/providers/:providerId/bookings/:bookingId/accept
117:     * @access Provider OWNER/ADMIN of the selected provider
118:     */
119:    async accept(request, response, next): Promise<void> {
120:      try {
121:        const params = providerBookingParamsSchema.parse(request.params);
122:        const body = versionBodySchema.parse(request.body);
123:        const data = await dependencies.service.accept({
124:          actorUserId: principalOf(response).userId,
125:          providerId: params.providerId,
126:          bookingId: params.bookingId,
127:          version: body.version,
128:          idempotencyKey: requireIdempotencyKey(request),
129:        });
130:        sendSuccess(request, response, 200, data);
131:      } catch (error) {
132:        next(mapZod(error));
133:      }
134:    },
135:
136:    /**
137:     * @desc Reject a confirmed booking with a seeded reason.
138:     * @route POST /api/v1/providers/:providerId/bookings/:bookingId/reject
139:     * @access Provider OWNER/ADMIN of the selected provider
140:     */
141:    async reject(request, response, next): Promise<void> {
142:      try {
143:        const params = providerBookingParamsSchema.parse(request.params);
144:        const body = reasonVersionBodySchema.parse(request.body);
145:        const data = await dependencies.service.reject({
146:          actorUserId: principalOf(response).userId,
147:          providerId: params.providerId,
148:          bookingId: params.bookingId,
149:          version: body.version,
150:          reasonCode: body.reasonCode,
151:          idempotencyKey: requireIdempotencyKey(request),
152:        });
153:        sendSuccess(request, response, 200, data);
154:      } catch (error) {
155:        next(mapZod(error));
156:      }
157:    },
158:
159:    /**
160:     * @desc Cancel an accepted booking as the selected provider.
161:     * @route POST /api/v1/providers/:providerId/bookings/:bookingId/cancel
162:     * @access Provider OWNER/ADMIN of the selected provider
163:     */
164:    async providerCancel(request, response, next): Promise<void> {
165:      try {
166:        const params = providerBookingParamsSchema.parse(request.params);
167:        const body = reasonVersionBodySchema.parse(request.body);
168:        const data = await dependencies.service.providerCancel({
169:          actorUserId: principalOf(response).userId,
170:          providerId: params.providerId,
