22:function sourceFiles(root: string): string[] {
23:  if (!existsSync(root)) {
24:    return [];
25:  }
26:  const result: string[] = [];
27:  for (const entry of readdirSync(root)) {
28:    const path = join(root, entry);
29:    if (statSync(path).isDirectory()) {
30:      result.push(...sourceFiles(path));
31:    } else if (extname(path) === ".ts") {
32:      result.push(path);
33:    }
34:  }
35:  return result;
