38:describe("R1-P16 bookings module boundaries and migration shape", () => {
39:  it("does not import payments Prisma, wallets, or configuration infrastructure", () => {
40:    const violations: string[] = [];
41:    for (const file of sourceFiles(bookingsRoot)) {
42:      const relativePath = relative(bookingsRoot, file).replaceAll("\\", "/");
43:      const source = readFileSync(file, "utf8");
44:      if (
45:        /#modules\/payments\/infrastructure/u.test(source) ||
46:        /#modules\/configuration\/infrastructure/u.test(source)
47:      ) {
48:        violations.push(`${relativePath} imported foreign infrastructure`);
49:      }
50:      if (
51:        relativePath === "bookings.response.service.ts" &&
52:        /#generated\/prisma|#database\/prisma/u.test(source)
53:      ) {
54:        violations.push("response service imported Prisma directly");
55:      }
56:    }
57:    expect(violations).toEqual([]);
58:  });
59:
60:  it("does not add fee, wallet, or refund-request columns in P16 SQL", () => {
61:    expect(migrationSql).not.toMatch(/CREATE TABLE "wallets"/u);
62:    expect(migrationSql).not.toMatch(/fee_minor|fee_amount|cancellation_fee/u);
63:    expect(migrationSql).not.toMatch(/CREATE TABLE "refund_requests"/u);
64:    expect(migrationSql.replace(/--[^\n]*/gu, "")).not.toMatch(/\bDROP TABLE\b/u);
65:    for (const table of [
66:      "cancellation_reasons",
67:      "booking_responses",
68:      "booking_cancellations",
69:      "booking_notification_intents",
70:      "booking_actor_commands",
71:    ]) {
72:      expect(migrationSql).toContain(`CREATE TABLE "${table}"`);
73:    }
74:  });
75:
76:  it("documents the P16 executable transition inventory", () => {
77:    for (const row of P16_EXECUTABLE_TRANSITIONS) {
78:      expect(migrationSql).toContain(`'${row.actor}', '${row.from}', '${row.to}'`);
79:    }
80:    expect(migrationSql).toContain("commercial.provider_response_hours");
81:    expect(migrationSql).toContain("PROVIDER_RESPONSE_EXPIRED");
82:    expect(isExecutableCustomerTransition("NONE", "DRAFT")).toBe(true);
83:    expect(isExecutableCustomerTransition("CONFIRMED", "CANCELLED")).toBe(false);
84:  });
